import os, re, fitz

def find_references_start(doc: fitz.Document):
    for i, page in enumerate(doc):
        txt = page.get_text().lower()
        # prefer heading-like occurrences
        if re.search(r'(?m)^\s*references\b', txt):
            return i
    for i, page in enumerate(doc):
        if 'references' in page.get_text().lower():
            return i
    return None

def refs_heading_y(page: fitz.Page):
    rects = page.search_for('References')
    if not rects:
        rects = page.search_for('REFERENCES')
    if not rects:
        return None
    return min(r.y0 for r in rects)

def collect_patterns(doc: fitz.Document, refs_page: int|None):
    max_page = (refs_page if refs_page is not None else len(doc))

    patterns=set()

    # metadata authors (full names)
    author_meta = (doc.metadata.get('author') or '').strip()
    if author_meta:
        for part in re.split(r'[;,]\s*', author_meta):
            part=part.strip()
            if len(part.split())>=2:
                patterns.add(part)

    # metadata subject / keywords sometimes contain venue
    subj=(doc.metadata.get('subject') or '').strip()
    if subj:
        patterns.add(subj)
    # common venue phrases (only if present in text)

    url_re=re.compile(r'https?://\S+')
    email_re=re.compile(r'[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}')
    arxiv_re=re.compile(r'(arXiv\s*:\s*\d{4}\.\d{4,5}(?:v\d+)?)', re.I)
    arxiv_url_re=re.compile(r'https?://arxiv\.org/abs/\S+', re.I)
    doi_re=re.compile(r'(10\.\d{4,9}/[-._;()/:A-Za-z0-9]+)')

    # scan pages before references for emails/urls/arxiv/doi and potential author+affiliation lines
    for pi in range(max_page):
        page=doc[pi]
        text=page.get_text()

        for m in email_re.findall(text):
            patterns.add(m)
        for m in arxiv_re.findall(text):
            patterns.add(m)
        for m in arxiv_url_re.findall(text):
            patterns.add(m)
        for m in doi_re.findall(text):
            # DOIs can leak via arXiv/published version; redact only if it appears near front-matter or contains the paper's own DOI.
            # We'll include it as a conservative measure.
            patterns.add(m)
        for m in url_re.findall(text):
            # remove trailing punctuation
            m=m.rstrip(').,;]')
            patterns.add(m)

        # front-matter heuristics: only look before Abstract on the first page
        if pi==0:
            lines=[ln.strip() for ln in text.splitlines() if ln.strip()]
            # find abstract line index
            abs_i=None
            for i,ln in enumerate(lines):
                if ln.lower()=='abstract' or ln.lower().startswith('abstract'):
                    abs_i=i
                    break
            header_lines=lines[:abs_i] if abs_i is not None else lines[:25]

            # author-like full names in header lines
            name_re=re.compile(r'\b([A-Z][a-zA-Z\-\']+\s+[A-Z][a-zA-Z\-\']+(?:\s+[A-Z][a-zA-Z\-\']+)?)\b')
            for ln in header_lines:
                # affiliations
                if any(k in ln for k in ['University','Institute','Laboratory','College','School','Inc.','LLC','Corp','Company','Adobe','Google','Microsoft','Amazon','Meta','Duke','Carnegie','Cornell','Georgia','Renmin','Kunshan']):
                    # split comma-separated affiliation lists
                    for seg in [s.strip() for s in re.split(r'\s*,\s*', ln) if s.strip()]:
                        if len(seg) >= 6:
                            patterns.add(seg)
                # correspondence
                if ln.lower().startswith('correspondence'):
                    patterns.add(ln)
                # names
                # only harvest names from lines that look like author lists
                if ln.count(',')>=2 or ' * ' in ln or '∗' in ln or any(ch.isdigit() for ch in ln):
                    for nm in name_re.findall(ln):
                        if len(nm.split())>=2 and len(nm) >= 6:
                            patterns.add(nm)

    # Add a few explicit venue strings if they appear in the document text
    venue_candidates=[
        'Proceedings of the International Conference on Machine Learning',
        'International Conference on Machine Learning',
        'Proceedings of the',
    ]
    for vc in venue_candidates:
        for pi in range(max_page):
            if vc.lower() in doc[pi].get_text().lower():
                patterns.add(vc)
                break

    # filter overly short patterns
    patterns={p for p in patterns if len(p.strip())>=6}
    return sorted(patterns, key=len, reverse=True)

