    if redc_len < orig_len * 0.7:
        raise ValueError(f"Too much removed: kept only {redc_len/orig_len:.0%}")

    orig.close(); redc.close()
    print('✓ Verification passed')


def redact_one(input_path, output_path):
    doc=fitz.open(input_path)
    refs_page=find_references_start(doc)
    patterns=collect_patterns(doc, refs_page)

    # figure references heading y on that page (to preserve references content on that page)
    refs_y=None
    if refs_page is not None:
        refs_y=refs_heading_y(doc[refs_page])

    max_page = (refs_page if refs_page is not None else len(doc))

    # Apply redactions page by page
    for pi in range(len(doc)):
        page=doc[pi]

        # pages after references page: skip entirely
        if refs_page is not None and pi > refs_page:
            continue

        # references page: only allow redactions above the References heading
        clip_y = None
        if refs_page is not None and pi == refs_page and refs_y is not None:
            clip_y = refs_y - 2

        for pat in patterns:
            rects = page.search_for(pat)
            if not rects:
                continue
            for r in rects:
                if clip_y is not None and r.y1 >= clip_y:
                    continue
                page.add_redact_annot(r, fill=(0,0,0))

        # Apply only if there are redactions on page
        try:
            page.apply_redactions()
        except Exception:
            # apply_redactions throws if no annotations on some versions; ignore
            pass

    # Clear identifying metadata
    meta = doc.metadata or {}
    for k in ['author','subject','creator','producer','keywords']:
        meta[k] = ''
    doc.set_metadata(meta)

    os.makedirs(os.path.dirname(output_path), exist_ok=True)
    doc.save(output_path, garbage=4, deflate=True, clean=True)
    doc.close()

    verify_redaction(input_path, output_path)

    # sanity check: ensure common leaks are gone before references
    red=fitz.open(output_path)
    rp=find_references_start(red)
    upto = (rp if rp is not None else len(red))
    all_txt='\n'.join(red[i].get_text() for i in range(upto))
    red.close()

    # report if any obvious identifiers remain
    leaks=[]
    for pat in patterns[:50]:  # check longer patterns first
        if pat and pat in all_txt:
            leaks.append(pat)
    if leaks:
        print('WARNING: some patterns still found in redacted text (first few):')
        for l in leaks[:10]:
            print('  ',l)


for i in (1,2,3):
    inp=f'/root/paper{i}.pdf'
    out=f'/root/redacted/paper{i}.pdf'
    print('\n=== Redacting', inp, '->', out, '===')
    redact_one(inp,out)

print('\nDone.')
