import os, re, fitz

def find_references_start(doc):
    for i in range(len(doc)):
        txt=doc[i].get_text().lower()
        if re.search(r'(?m)^\s*(?:\d+\s*\.?\s*)?references\b', txt):
            return i
    for i in range(len(doc)):
        if re.search(r'\breferences\b', doc[i].get_text().lower()):
            return i
    return None

def extract_author_names_from_frontmatter(page0_text: str):
    lines=[ln.strip() for ln in page0_text.splitlines() if ln.strip()]
    abs_i=None
    for i,ln in enumerate(lines):
        if ln.lower()=='abstract' or ln.lower().startswith('abstract'):
            abs_i=i
            break
    header=lines[:abs_i] if abs_i is not None else lines[:40]

    # keep only likely author lines (exclude affiliation lines)
    author_lines=[]
    for ln in header:
        if any(k in ln for k in ['University','Institute','Laboratory','College','School']):
            continue
        if ln.count(',')>=1 and any(ch.isdigit() for ch in ln) or '∗' in ln or '*' in ln:
            author_lines.append(ln)
    if not author_lines:
        # fallback: any line with multiple commas before abstract
        author_lines=[ln for ln in header if ln.count(',')>=2]

    blob=' '.join(author_lines)
    parts=[p.strip() for p in blob.split(',') if p.strip()]

    names=set()
    for p in parts:
        toks=re.findall(r"[A-Za-z\-']+", p)
        if len(toks)>=2:
            nm=f"{toks[0]} {toks[1]}"
